/* =========================================================
   UX Smooth — Phase style-inject (G1/G2/G3/G4)
   ========================================================= */
.primary-action{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:10px 14px 4px;background:linear-gradient(180deg,var(--card) 0%,transparent 100%);border-bottom:1px solid var(--line);}
.primary-action .pab{display:flex;align-items:center;justify-content:flex-start;gap:10px;height:48px;border-radius:12px;background:var(--card);color:var(--text);border:1px solid var(--line);box-shadow:0 1px 0 rgba(0,0,0,.02);font-size:14px;font-weight:600;padding:0 14px;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:transform .05s ease;}
.primary-action .pab:active{transform:scale(.98);}
.primary-action .pab .emj{font-size:22px;line-height:1;}
.primary-action .pab.pab-cn{border-color:#e8dcc4;}
.primary-action .pab.pab-wu{border-color:#ddd6ee;}
.primary-action .pab.pab-al{border-color:#ecd1b9;}
.primary-action .pab.pab-qc{border:1px dashed var(--line);background:transparent;color:var(--text-hint);}

.result-next-steps{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px;padding:10px;border-radius:10px;background:var(--bg);border:1px dashed var(--line);}
.result-next-steps .rns{flex:1 1 40%;display:flex;align-items:center;justify-content:center;gap:6px;height:40px;border-radius:8px;background:var(--card);color:var(--text);border:1px solid var(--line);font-weight:600;font-size:13px;cursor:pointer;}
.result-next-steps .rns.rns-primary{background:var(--pri);color:#fff;border-color:transparent;}
.result-next-steps .rns.rns-hint{background:transparent;color:var(--text-hint);border:1px dashed var(--line);}

#quickCmdModal{position:fixed;inset:0;z-index:99998;background:rgba(0,0,0,.35);display:none;align-items:flex-start;justify-content:center;padding-top:18vh;}
#quickCmdModal.show{display:flex;}
#quickCmdModal .qc-panel{width:min(560px,92vw);background:var(--card);border-radius:14px;border:1px solid var(--line);box-shadow:0 12px 40px rgba(0,0,0,.2);overflow:hidden;}
#quickCmdModal .qc-input{width:100%;height:48px;border:0;outline:0;padding:0 16px;font-size:16px;background:var(--card);color:var(--text);border-bottom:1px solid var(--line);}
#quickCmdModal .qc-candidates{max-height:52vh;overflow:auto;}
#quickCmdModal .qc-row{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px dashed var(--line);cursor:pointer;}
#quickCmdModal .qc-row:last-child{border-bottom:0;}
#quickCmdModal .qc-row.active, #quickCmdModal .qc-row:active{background:var(--pri-light);}
#quickCmdModal .qc-row .k{font-weight:700;color:var(--pri-dark);min-width:28px;text-align:center;font-size:13px;}
#quickCmdModal .qc-row .lbl{flex:1;font-size:14px;}
#quickCmdModal .qc-row .sub{font-size:11px;color:var(--text-hint);}
#quickCmdModal .qc-foot{display:flex;align-items:center;justify-content:space-between;padding:8px 12px;border-top:1px solid var(--line);background:var(--bg);font-size:11px;color:var(--text-hint);}
#quickCmdModal .qc-foot button{background:transparent;border:1px solid var(--line);border-radius:6px;color:var(--text-hint);height:28px;padding:0 10px;cursor:pointer;}

#compareModal{position:fixed;inset:0;z-index:99997;background:rgba(0,0,0,.45);display:none;align-items:center;justify-content:center;padding:14px;}
#compareModal.show{display:flex;}
#compareModal .cm-panel{width:min(960px,96vw);max-height:94vh;overflow:auto;background:var(--card);border-radius:14px;border:1px solid var(--line);box-shadow:0 12px 60px rgba(0,0,0,.3);}
#compareModal .cm-head{display:flex;align-items:center;justify-content:space-between;padding:12px 14px;border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--card);z-index:2;}
#compareModal .cm-head .title{font-weight:700;font-size:15px;}
#compareModal .cm-head .close{background:transparent;border:1px solid var(--line);border-radius:8px;height:32px;padding:0 12px;color:var(--text);cursor:pointer;}
#compareModal .cm-diff-bar{margin:10px 14px;padding:8px 12px;border-radius:10px;background:var(--bg);border:1px solid var(--line);font-size:12px;}
#compareModal .cm-body{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:10px 14px 14px;}
#compareModal .cm-col{min-width:0;border-radius:10px;border:1px solid var(--line);background:var(--bg);padding:10px;}
#compareModal .cm-col h3{font-size:13px;margin-bottom:6px;}
#compareModal .cm-col .cm-meta{font-size:11px;color:var(--text-hint);margin-bottom:6px;}
#compareModal .cm-col .cm-content{font-size:12px;line-height:1.55;max-height:55vh;overflow:auto;word-break:break-word;}
#compareModal .cm-foot{display:flex;align-items:center;justify-content:flex-end;gap:8px;padding:10px 14px;border-top:1px solid var(--line);background:var(--bg);position:sticky;bottom:0;}
#compareModal .cm-foot button{height:34px;padding:0 12px;border-radius:8px;border:1px solid var(--line);background:var(--card);color:var(--text);cursor:pointer;}
#compareModal .cm-foot button.primary{background:var(--pri);color:#fff;border-color:transparent;}
@media (max-width: 520px){
  #compareModal .cm-body{grid-template-columns:1fr;}
}

#errBanner{position:fixed;top:0;left:0;right:0;z-index:99999;background:#D32F2F;color:#fff;padding:9px 14px;font-size:13px;line-height:1.45;box-shadow:0 3px 12px rgba(211,47,47,.3);display:none;}
#errBanner.show{display:block;animation:ebFade .3s ease;}
#errBanner .row{display:flex;justify-content:space-between;gap:10px;align-items:center;}
#errBanner .msg{flex:1;min-width:0;}
#errBanner .msg .t{font-weight:800;margin-right:6px;}
#errBanner .btns{display:flex;gap:6px;flex-shrink:0;}
#errBanner .btns button{border:0;border-radius:6px;height:28px;padding:0 10px;font-weight:700;cursor:pointer;font-size:12px;}
#errBanner .btns .b-retry{background:#fff;color:#D32F2F;}
#errBanner .btns .b-fb{background:rgba(255,255,255,.15);color:#fff;}
#errBanner .btns .b-close{background:rgba(0,0,0,.25);color:#fff;}
#errBanner .detail{margin-top:6px;opacity:.9;font-size:11px;max-height:64px;overflow:auto;word-break:break-all;}
body.banner-show{padding-top:40px;}
@keyframes ebFade{from{transform:translateY(-100%);}to{transform:none;}}

.batch-bar{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:6px 10px;background:var(--pri-light);border-bottom:1px solid var(--line);font-size:12px;}
.batch-bar .l{display:flex;align-items:center;gap:8px;}
.batch-bar .l input{width:18px;height:18px;}
.batch-bar .r{display:flex;gap:4px;}
.batch-bar .r button{height:32px;padding:0 10px;border-radius:6px;border:1px solid var(--line);background:var(--card);cursor:pointer;font-size:12px;}
.batch-bar .r button.danger{color:#D32F2F;font-weight:700;}
.batch-bar.hide{display:none;}
.hist-item-row{display:flex;align-items:center;gap:8px;}
.hist-item-row input[type=checkbox]{width:18px;height:18px;}

.toast-bottom{position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,.75);color:#fff;padding:8px 14px;border-radius:20px;font-size:12px;z-index:99995;pointer-events:none;opacity:0;transition:opacity .3s ease;}
.toast-bottom.show{opacity:1;}

.wuge-single{display:flex;gap:6px;margin-bottom:8px;}
.wuge-single input{flex:1;height:40px;border-radius:8px;border:1px solid var(--line);padding:0 10px;font-size:15px;background:var(--card);color:var(--text);}
.wuge-single button{height:40px;padding:0 12px;border-radius:8px;border:1px solid var(--line);background:var(--bg);cursor:pointer;}
.wuge-single-hint{font-size:11px;color:var(--text-hint);margin-bottom:6px;}
.wuge-single-hint .toggle-manual{color:var(--pri-dark);cursor:pointer;text-decoration:underline;}

.draft-hint{font-size:11px;color:var(--pri-dark);margin:4px 0;}

/* mini-skeleton */
.sk{background:linear-gradient(90deg,var(--bg) 0%,var(--card) 50%,var(--bg) 100%);background-size:200% 100%;animation:sk 1.2s linear infinite;border-radius:6px;}
@keyframes sk{0%{background-position:200% 0;}100%{background-position:-200% 0;}}
